using UnityEngine;
public sealed class GridShiftFactoryStation:MonoBehaviour {
 public string command;
 public void AuthorScene(){Start();foreach(var a in GetComponentsInChildren<GridShiftWorldAction>())a.sceneAuthored=true;}
 void Start(){var ops=DeliveryManager.Instance?.GetComponent<GridShiftActiveOperations>();string title=command=="exit"?"Sair do centro de distribuição":command=="attendant"?"Conversar com atendente":command=="accept"?"Consultar pedidos":command=="scan"?"Conferir encomenda":command.StartsWith("pack")?"Embalar encomenda":command=="release"?"Liberar expedição":command.StartsWith("sort")?"Consultar / separar setor "+(command=="sort-a"?"A":"B"):command=="label"?"Imprimir etiqueta":command=="administration"?"Consultar administração":"Delegar ao operador contratado";
  var action=GridShiftWorldAction.Create(transform,title,Vector3.zero,p=>{if(command=="exit"){WorldSession.Instance.RequestTransition("SampleScene",p.transform);return true;}if(command=="attendant"||command=="accept"){GridShiftFactoryInterior.Instance.attendantPoint.GetComponent<GridShiftDepotAttendant>().Open(p,command=="accept");return true;}if(command=="administration"){p.GetComponent<PortableTablet>()?.Open();return true;}return ops.Execute(p,command,command=="scan"?"PKG-"+DeliveryManager.Instance.PersonalOrder?.id:DeliveryManager.Instance.PersonalOrder?.id,out _);});action.available=()=>{var order=DeliveryManager.Instance.PersonalOrder;if(command=="scan")return order!=null&&order.depotPicked&&!order.depotScanned;if(command.StartsWith("sort"))return order!=null&&!order.depotTutorial&&order.depotLabelled&&!order.depotSorted;if(command=="label")return order!=null&&order.depotPacked&&!order.depotLabelled;if(command.StartsWith("pack"))return order!=null&&order.depotScanned&&!order.depotPacked;if(command=="release")return order!=null&&!order.depotReleased&&order.depotSorted;return true;};if(action.sceneAuthored)return;action.focusOffset=Vector3.up*(command=="attendant"?1.2f:.9f);action.focusSize=new Vector3(1.6f,2,1.4f);if(command=="exit"){action.focusOffset=new Vector3(0,1.2f,-.9f);action.focusSize=new Vector3(1.6f,2.4f,1);}else if(command=="attendant"){action.focusOffset=Vector3.up*1.2f;}else if(command.StartsWith("sort")){action.focusOffset=new Vector3(-.7f,1,0);}else if(command=="label"){action.focusOffset=new Vector3(-.5f,1,0);}else action.focusOffset=new Vector3(0,1,.7f);
 }
}
